parameters.jsCode:
const ctx = $('Merge Email and Classification').first().json;
const rows = $input.all()
  .map(i => i.json)
  .map(r => Object.assign({ id: r.id }, r.fields || r))
  .filter(r => r.id && r.Answer);
const kbContext = rows
  .map((r, idx) => 'Entry ' + (idx + 1) + ' | Topic: ' + (r.Question || '') + '\nResolution: ' + (r.Answer || ''))
  .join('\n\n');
const replyLanguage = /[\u0600-\u06FF]/.test(ctx.body_text || '') ? 'Arabic' : 'the same language as the customer email';
return [{
  json: Object.assign({}, ctx, {
    kb_found: rows.length > 0,
    kb_match_count: rows.length,
    kb_context: kbContext,
    reply_language: replyLanguage
  })
}];

