parameters.jsCode:
const ctx = $('Assemble Draft').first().json;
const byName = {};
for (const item of $input.all()) {
  const l = item.json;
  if (l && l.name) byName[l.name] = l.id;
}
const wanted = ['AI-Triaged', 'Needs-Review'];
if (ctx.is_urgent) wanted.push('AI-Urgent');
const missing = wanted.filter(n => !byName[n]);
if (missing.length) {
  throw new Error('Missing Gmail labels: ' + missing.join(', ') + '. Run the "Setup: Create Gmail Labels" branch once, then retry.');
}
return [{ json: { thread_id: ctx.thread_id, label_ids: wanted.map(n => byName[n]) } }];
